#include <stdio.h>

/* p03 Number Guessing: loop until the guess matches.
   TODO: randomise the secret with rand() and count tries. */
int main(void) {
    int secret = 7, guess = 0, tries = 0;
    while (guess != secret) {
        printf("guess: ");
        if (scanf("%d", &guess) != 1) return 1;
        tries++;
    }
    printf("correct in %d tries\n", tries);
    return 0;
}

