#include <stdio.h>

/* p09 Inventory Management: stock in memory, then on disk.
   TODO: load the file back and support add/remove. */
struct Item { char name[24]; int qty; };

int main(void) {
    struct Item stock[2] = {{"pen", 40}, {"notebook", 12}};
    FILE *f = fopen("stock.txt", "w");
    if (!f) { perror("stock.txt"); return 1; }
    for (int i = 0; i < 2; i++) fprintf(f, "%s %d\n", stock[i].name, stock[i].qty);
    fclose(f);
    puts("wrote stock.txt");
    return 0;
}

