#include <stdio.h>

/* p12 File-Based Student Database: one binary record.
   TODO: add a record, then read every record back. */
struct Student { int roll; char name[32]; };

int main(void) {
    struct Student s = {1, "Ahetesham"};
    FILE *f = fopen("students.dat", "wb");
    if (!f) { perror("students.dat"); return 1; }
    fwrite(&s, sizeof s, 1, f);
    fclose(f);
    printf("saved %zu bytes\n", sizeof s);
    return 0;
}

