int main(void) {
    struct Node *head = malloc(sizeof *head);
    if (!head) return 1;
    head->value = 42;
    head->next = NULL;
    printf("head=%d\n", head->value);
    free(head);
    return 0;
}

#include <stdio.h>

/* p15 Expression Evaluator: a fixed-size stack is enough to start.
   TODO: push/pop helpers and postfix parsing. */
int main(void) {
    int stack[16], top = -1;
    stack[++top] = 2;
    stack[++top] = 3;
    int b = stack[top--], a = stack[top--];
    printf("2 + 3 = %d\n", a + b);
    return 0;
}
